/bin/bash -lc "python3 - <<'PY'
import json,re,decimal
from pathlib import Path
D=decimal.Decimal
def numeric(s):
 a=re.findall(r'-?[0-9][0-9,.]*',s)
 try:return D(a[-1].replace(',','').rstrip('.'))
 except:return None
for p in sorted(Path('results/run60/val_generations').glob('[0-9]*.jsonl'),key=lambda p:int(p.stem)):
 rows=[json.loads(l) for l in p.open()]; ok=[numeric(r['output'])==D(r['gts']) for r in rows]; mismatch=[r for r,k in zip(rows,ok) if k"'!=bool(r['"'score'])]
 print(p.stem,len(rows),'logged',sum(r['score'] for r in rows)/len(rows),'numeric',sum(ok)/len(rows),'mismatch',len(mismatch),'no final marker',sum('####' not in r['output'] and 'boxed' not in r['output'] for r in rows))
 if p.stem=='60':
  for r in mismatch[:8]:print('GT',r['gts'],'score',r['score'],'tail',repr(r['output'][-200:]))
for p in Path('results/run60/rollouts').glob('[0-9]*.jsonl'):
 rows=[json.loads(l) for l in p.open()]; print('rollout',p.stem,'keys',rows[0].keys()); print('numeric',sum(numeric(r['output'])==D(r['gts']) for r in rows)/len(rows),'score',sum(r['score'] for r in rows)/len(rows))
ms=[json.loads(l) for l in open('results/run60/metrics.jsonl')]
for a,b in [(1,10),(51,60)]:
 ds=[r['data'] for r in ms if a<=r['step']<=b]
 print(a,b,{k:round(sum(d[k] for d in ds)/len(ds),6) for k in ['critic/score/mean','response_length/clip_ratio','response_length/mean','actor/entropy','actor/grad_norm','actor/pg_clipfrac','actor/kl_loss','timing_s/step']})
PY"
